/**
 * When native Forwarded fails: download media and re-send with typing + unique jitter.
 */
async relayMediaFallbackAcrossBridge({
  message,
  session,
  direction,
  destPhone,
  destChatIds,
  code,
  caption = '',
  msgType = '',
}) {
  const toCustomer = direction === 'desk_to_customer';
  const media = await this.downloadMediaWithRetry(message);
  if (!media?.data) {
    console.error(
      `[ChatBridge] Media fallback failed — could not download (${direction})`
    );
    MessageLog.add({
      direction: 'out',
      phone: destPhone || 'unknown',
      body: `[bridge ${direction} media-fallback-FAILED]`,
      meta: { session_id: session.id, session_code: code, direction },
    });
    return;
  }

  const type = String(msgType || message.type || '').toLowerCase();
  const mime = String(media.mimetype || '').toLowerCase();
  const isVoice = type === 'ptt' || type === 'audio';
  const isDoc =
    type === 'document' ||
    mime.includes('pdf') ||
    mime.includes('msword') ||
    mime.includes('officedocument');

  let destChatId = destChatIds[0];
  const sent = await this.sendMedia(destPhone, media, {
    chatId: destChatId,
    caption: caption || undefined,
    sendAudioAsVoice: isVoice,
    sendMediaAsDocument: isDoc,
    skipReading: true,
  });

  if (sent?._outboundChatId) destChatId = sent._outboundChatId;

  if (toCustomer) {
    ChatSessions.bindCustomerChatId(session.id, destChatId);
  } else {
    ChatSessions.bindDeskChatId(session.id, destChatId);
  }
  ChatSessions.touch(session.id, {
    side: toCustomer ? 'desk' : 'customer',
    ...(toCustomer
      ? { customer_chat_id: destChatId }
      : { desk_chat_id: destChatId }),
  });

  const waId = sent?.id?._serialized || sent?.id?.$1 || sent?.id?.id || null;
  if (waId) {
    ChatSessions.trackMessage(session.id, direction, waId, caption || '[media]');
  }

  MessageLog.add({
    direction: 'out',
    phone: destPhone,
    body: `[bridge ${direction} media-fallback] ${caption || '[media]'}`,
    meta: {
      session_id: session.id,
      session_code: code,
      direction,
      native: false,
      media_fallback: true,
      dest_chat_id: destChatId,
      wa_id: waId,
    },
  });
  console.log(
    `[ChatBridge] Media fallback OK #${session.id}[${code}] → ${destChatId}`
  );
}

